INSERT INTO kb_document_chunk(
    state, tiny_i8, small_i16, big_i64, u8_val, u16_val, u32_val, u64_val,
    nullable_int, f32_val, f64_val, flag, letter, name, varchar_val, enabled, score, dec_val,
    payload, event_date, event_time, event_ts, json_val, jsonb_val
) VALUES (
    #{state}, #{tiny_i8}, #{small_i16}, #{big_i64}, #{u8_val}, #{u16_val}, #{u32_val}, #{u64_val},
    #{nullable_int}, #{f32_val}, #{f64_val}, #{flag}, #{letter}, #{name}, #{varchar_val}, #{enabled}, #{score}, #{dec_val}::numeric,
    decode(#{payload}, 'hex'), #{event_date}::date, #{event_time}::time, #{event_ts}::timestamp, #{json_val}::json, #{jsonb_val}::jsonb
);
